let lastTime = context.get("lastTime") || 0;
let now = Date.now();

if (lastWeight !== undefined) {
    let diff = Math.abs(weight - lastWeight);

    if (diff < minChange) return null;
    if (now - lastTime < stableDelay) return null;
}

context.set("lastWeight", weight);
context.set("lastTime", now);

msg.payload = weight-ZERO_OFFSET;
return msg;

