let weight = Number(msg.payload);
if (!Number.isFinite(weight)) return null;

weight = Math.max(0, weight);

// ======================================================
// SETTINGS (HOME SCALE, IN POUNDS)
// ======================================================

const NOISE_TOLERANCE = 0.3;  // test: 0.05  // real: 0.3
const REMOVAL_DROP = 1;  // test: 0.5  // real: 1

// Weight below this means the scale is effectively empty
const EMPTY_THRESHOLD = 0.15;  // test: 0.15  // real: 0.15

// Returning within this range means probably same bag
const BAG_RETURN_TOLERANCE = 2;  // test: 0.3  // real: 2.0

// Wait after something returns to the scale
const RETURN_SETTLE_MS = 2000;

// ======================================================
// STORED STATE
// ======================================================

let lastWeight = flow.get("lastWeight");
let savedTotal = flow.get("savedTotal") || 0;

// States: NORMAL, REMOVING, EMPTY, SETTLING
let bagState = flow.get("bagState") || "NORMAL";

let oldBagWeight = flow.get("oldBagWeight") || 0;
let returnStartTime = flow.get("returnStartTime");

const now = Date.now();

// ======================================================
// HELPERS
// ======================================================

function display(total) {
    msg.payload = Number(total.toFixed(2));
    return msg;
}

function setStatus(color, message) {
    node.status({
        fill: color,
        shape: "dot",
        text: message
    });
}

function resetBagState() {
    flow.set("bagState", "NORMAL");
    flow.set("oldBagWeight", 0);
    flow.set("returnStartTime", undefined);
}

// ======================================================
// FIRST READING
// ======================================================

if (lastWeight === undefined || lastWeight === null) {
    flow.set("lastWeight", weight);
    return display(savedTotal + weight);
}

// ======================================================
// NORMAL OPERATION
// ======================================================

if (bagState === "NORMAL") {

    const difference = weight - lastWeight;

    // Normal increase or tiny fluctuation
    if (difference >= -NOISE_TOLERANCE) {

        flow.set("lastWeight", weight);

        return display(savedTotal + weight);
    }

    // Possible removal
    if (difference <= -REMOVAL_DROP) {

        oldBagWeight = lastWeight;
        flow.set("oldBagWeight", oldBagWeight);

        if (weight <= EMPTY_THRESHOLD) {

            flow.set("bagState", "EMPTY");
            setStatus("yellow", "Bag removed - waiting");

        } else {

            flow.set("bagState", "REMOVING");
            setStatus("yellow", "Possible bag removal");
        }

        return display(savedTotal + oldBagWeight);
    }

    // Ignore small decreases
    return display(savedTotal + lastWeight);
}

// ======================================================
// POSSIBLE REMOVAL IN PROGRESS
// ======================================================

if (bagState === "REMOVING") {

    // Scale became empty
    if (weight <= EMPTY_THRESHOLD) {

        flow.set("bagState", "EMPTY");
        setStatus("yellow", "Scale empty - waiting");

        return display(savedTotal + oldBagWeight);
    }

    // Weight returned near original before reaching zero
    if (
        Math.abs(weight - oldBagWeight)
        <= BAG_RETURN_TOLERANCE
    ) {

        flow.set("lastWeight", weight);
        resetBagState();

        setStatus("green", "Removal canceled");

        return display(savedTotal + weight);
    }

    // Still being removed
    return display(savedTotal + oldBagWeight);
}

// ======================================================
// SCALE EMPTY
// ======================================================

if (bagState === "EMPTY") {

    // Wait indefinitely while scale is empty
    if (weight <= EMPTY_THRESHOLD) {

        setStatus("yellow", "Waiting for bag to return");

        return display(savedTotal + oldBagWeight);
    }

    // Something has returned: start settling period
    flow.set("bagState", "SETTLING");
    flow.set("returnStartTime", now);

    setStatus("yellow", "Bag returned - settling");

    return display(savedTotal + oldBagWeight);
}

// ======================================================
// SETTLING PERIOD
// ======================================================

if (bagState === "SETTLING") {

    // If bag is lifted again, restart the process
    if (weight <= EMPTY_THRESHOLD) {

        flow.set("bagState", "EMPTY");
        flow.set("returnStartTime", undefined);

        setStatus("yellow", "Scale empty again");

        return display(savedTotal + oldBagWeight);
    }

    const elapsed = now - (returnStartTime ?? now);

    // Keep cumulative total frozen during settling
    if (elapsed < RETURN_SETTLE_MS) {

        const remaining = Math.ceil(
            (RETURN_SETTLE_MS - elapsed) / 1000
        );

        setStatus(
            "yellow",
            "Settling: " + remaining + "s"
        );

        return display(savedTotal + oldBagWeight);
    }

    // --------------------------------------------------
    // SETTLING COMPLETE: COMPARE WEIGHTS
    // --------------------------------------------------

    const returnDifference =
        Math.abs(weight - oldBagWeight);

    // Same bag returned
    if (returnDifference <= BAG_RETURN_TOLERANCE) {

        flow.set("lastWeight", weight);
        resetBagState();

        setStatus("green", "Same bag returned");

        return display(savedTotal + weight);
    }

    // --------------------------------------------------
    // NEW BAG DETECTED
    // --------------------------------------------------

    savedTotal += oldBagWeight;
    flow.set("savedTotal", savedTotal);

    flow.set("lastWeight", weight);

    let bagCount = flow.get("bagCount") || 0;
    bagCount++;
    flow.set("bagCount", bagCount);

    resetBagState();

    setStatus("green", "New bag detected");

    return display(savedTotal + weight);
}

// ======================================================
// FALLBACK
// ======================================================

resetBagState();
return display(savedTotal + weight);

